def request_with_retry(client, request, policy, sleep=time.sleep):
    attempt = 0
    while True:
        response = client.send(request)
        if response.status_code == 429:
            if attempt >= policy.max_retries:
                raise QuotaExceeded(
                    f"upstream returned 429 after {attempt} retries"
                )
            delay = None
            if policy.respect_retry_after:
                delay = retry_after_seconds(response)
            if delay is None:
                delay = backoff_delay(policy, attempt)
            sleep(min(delay, policy.backoff_max))
            attempt += 1
            continue
        if response.status_code not in RETRYABLE_STATUS or attempt >= policy.max_retries:
            return response
        sleep(backoff_delay(policy, attempt))
        attempt += 1
